('spmb-sekolah-anak-saleh-cache-spmb_app_settings_map', 'a:62:{s:11:\"school_name\";s:18:\"Sekolah Anak Saleh\";s:17:\"portal_hero_title\";s:55:\"Membangun Generasi Cerdas, Sholeh, dan Berakhlak Mulia.\";s:23:\"portal_hero_description\";s:169:\"Bergabunglah bersama Sekolah Anak Saleh. Kami menyajikan kurikulum yang mengintegrasikan nilai-nilai Islam dengan pendidikan modern untuk menyiapkan pemimpin masa depan.\";s:15:\"spmb_qrcode_url\";s:24:\"https://spmb.sans.sch.id\";s:11:\"winpay_mode\";s:10:\"production\";s:18:\"winpay_merchant_id\";s:16:\"MOCK_MERCHANT_ID\";s:17:\"winpay_client_key\";s:15:\"MOCK_CLIENT_KEY\";s:20:\"winpay_client_secret\";s:18:\"MOCK_CLIENT_SECRET\";s:18:\"winpay_private_key\";s:0:\"\";s:17:\"winpay_public_key\";s:0:\"\";s:26:\"winpay_sandbox_merchant_id\";s:9:\"171001519\";s:25:\"winpay_sandbox_client_key\";s:36:\"f754edbc-dc93-49e6-986a-1e9e18158938\";s:28:\"winpay_sandbox_client_secret\";s:21:\"SANDBOX_CLIENT_SECRET\";s:26:\"winpay_sandbox_private_key\";s:1730:\"-----BEGIN PRIVATE KEY-----\r\nMIIEvgIBADANBgkqhkiG9w0BAQEFAASCBKgwggSkAgEAAoIBAQDQHqtVMsLLWxY8\r\n7hPUHbPxzmniCUjjp8fctjPvqOH1CZZWTeBKN4ag0jiFy0/wYhFvEYS4JhdTuNoc\r\nvuJmffHKJuvMCu3C6g7FxlBYobtQWKmBng1lVJ1Iyz6NrewNVXANmfycFdXuCH6M\r\nRQ6vudS5H5QCdWtu3pBkkaHSJaWzy0B6KUKfKT25kJ9Ncsv2tjT1H3NlqkxQvp8Y\r\ncYsHMiL15jPnP1v+pa82O6u/WBXFxKJ1DaybG8dy60cuDEpN6M1DwrziemSmBRrw\r\nb1I4LOe5duBR3r6JGW3qPkgtFp2O/PXGRJHBfd8CxJzhTLrSF+1prBJ454oywq92\r\nzqXESRnhAgMBAAECggEAVicUAtlYBOmIe6GMiMbg+izZ7Q2t5DvMwwOT3VZ6bz7Q\r\nQprLSb3Rl9peNpiS124pTGKin7548pn3hGXKf+YMBQR2oQk3InRUuC9fjEkrKtgB\r\nF1yPrA5Ka9ti4jCIon5nO+IuTYjGfdp7VGKz8S+KrTWyxg/IcOVmPZOBuuYFwbaW\r\ntPb6Fil3beijrPzB0yrP0hF82CxqbLY3Tg0BOZiXrFNFjmyckcfTERYIaUBhTuAX\r\nsPceBX2bGt6Wu50Agv0LbDc66jIZvsS11hoKu1TSo8yOkvZoL+9LKOW84pCFJDX0\r\n6U70Gwy7wfBpdKf+WOCs/Fr/zQKbgVujfLMA06JUZwKBgQD4XvoG1dc4pwbyrfs1\r\nxxBmM7B0ASxSqHJ448wvKEAyb1ME6wKTBXGjDNYbdFLVX+vpTEtHeSHkMu+hR1yF\r\njYsRfltSu/vJT2z3VPd/3h2iDx5owwcGcPP45Ad/iLhmIl+0gbaxMkBpqJCF+rRs\r\n+iKn5soxNHwP1Y