(30, 'footer_copyright_text', '© 2026 {SchoolName}. All rights reserved.', '2026-09-04 01:24:33', '2026-09-04 01:24:33'),
(31, 're_registration_instructions_unpaid', '', '2026-09-04 01:24:33', '2026-09-04 01:24:33'),
(32, 're_registration_instructions_completed', '', '2026-09-04 01:24:33', '2026-09-04 01:24:33'),
(33, 'unit_paud_desc', 'Terwujudnya pendidikan usia dini unggul islami yang menghasilkan murid beriman, bertaqwa, berakhlak, merdeka, berkualitas, kreatif, dan inovatif yang berperadaban dan ramah kehidupan berilmu pengetahuan teknologi informasi, berprestasi, berbudaya, dan berbakti kepada agama, bangsa, dan keluarga berbasis Panca Karakter Anak Saleh.', '2026-09-04 01:24:33', '2026-09-16 14:33:29'),
(34, 'unit_paud_content', 'Kurikulum PG-TK-Daycare Anak Saleh yang mengusung misi membangun “Generasi Insan Kamil”. Pendekatan ini memadukan fondasi pendidikan nasional dengan nilai-nilai karakter yang luas yaitu\r\nProgram Layanan  antara lain : PG, TK, Daycare dan TPQ', '2026-09-04 01:24:33', '2026-09-17 11:52:21'),
(35, 'unit_paud_features', 'Everyday with Al-Qur’an & Sunnah\r\nLiteracy program : language literacy, digital literacy, inclusive culture literacy\r\nThematic Fun Project\r\nGardening & Farming\r\nExcursion Study & Outbound Program\r\nFamily Inn\r\nAssessment and Mapping student potential\r\nCelebrating a Big Theme\r\nCelebrating of religion and National Days\r\nYears Special Program\r\nMulti Moment Competition for Children\r\nCharity & Social Service\r\nIslamic Parents School / Parenting\r\nHealth Screening\r\nEducational Counseling\r\nAnak Saleh Got Talent / Performance day', '2026-09-04 01:24:33', '2026-09-16 15:02:15'),
(36, 'unit_paud_requirements', '1. Scan Asli AKTA Kelahiran ananda\r\n2. Scan Asli KK (Kartu Keluarga)\r\n3. Foto Diri ananda ( wajah tampak jelas)\r\n4. Scan Asli File Assesment (Bagi ananda yang pernah/sedang mengikuti terapi berkebutuhan khusus)\r\n\r\n*Tambahan jika ananda adalah peserta didik pindahan atau mutasi\r\n5. Scan Asli Rapot Terakhir ananda\r\n6. Scan Asli Surat keterangan dari sekolah lama\r\n7. Kartu NISN (Nomor Induk Siswa Nasional)/Surat Keterangan NISN dari sekolah lama', '2026-09-04 01:24:33', '2026-09-16 14:52:09'),
(37, 'unit_paud_flow', 'Pembuatan Akun & Registrasi Awal di Portal SPMB\r\nPembayaran Biaya Awal Pendaftaran (Enrollment Fee)\r\nPengisian Formulir Lengkap & Unggah Dokumen Berkas\r\nVerifikasi & Validasi Berkas oleh Panitia SPMB\r\nAssessment Siswa & Sesi Ta\'aruf\r\nPengumuman Hasil Seleksi & Persetujuan Pernyataan\r\nDaftar Ulang & Penyelesaian Administrasi Akhir', '2026-09-04 01:24:33', '2026-09-12 01:59:45'),
(38, 'unit_sd_desc', 'SD Anak Saleh Malang adalah sekolah unggulan yang berkomitmen melahirkan generasi Qurani dan berkarakter mulia. Berlandaskan lima pilar karakter: Kesalehan Personal, Kesalehan Sosial, Kesalehan Kealamiahan, Kesalehan Kebangsaan, dan Kesalehan Kecendekiaan, kami mempersiapkan peserta didik untuk menjadi individu cerdas dan saleh, siap berkontribusi bagi bangsa dan agama.', '2026-09-04 01:24:33', '2026-09-15 13:54:43'),
(39, 'unit_sd_content', 'Special curriculum of Anak Saleh\r\nInternational curriculum\r\nNational curriculum\r\nIslamic curriculum', '2026-09-04 01:24:33', '2026-09-15 14:29:35'),
(40, 'unit_sd_features', 'Everyday with Al-Qur’an & Sunnah\r\nLiteracy program: language literacy, digital literacy, inclusive culture literacy\r\nThematic Fun Project\r\nIntensive Learning Program\r\nHybrid Learning\r\nGardening and Farming\r\nMoving Home\r\nProject Based Learning\r\nExcursion Study & Outbound Program\r\nStudy Tour\r\nAssessment and Mapping Student Potential\r\nCelebrating of Religion and National Day\r\nYears Special Program\r\nMulti Moment Competition for Student\r\nCharity & Social Service\r\nIslamic Parents School / Parenting\r\nHealth Screening\r\nEducational Counseling\r\nAnak Saleh Got Talent / Student Day', '2026-09-04 01:24:33', '2026-09-15 13:46:40'),
(41, 'unit_sd_requirements', 'Mengisi Formulir Pendaftaran,\r\nScan Akta Kelahiran\r\nScan Kartu Keluarga\r\nScan Surat Keterangan Murid Aktif Dari Sekolah Asal\r\nPassphoto Formal\r\nScan NISN\r\nScan Surat Hasil Assessment Dari Psikolog (khusus MBK / Murid Berkebutuhan Khusus)', '2026-09-04 01:24:33', '2026-09-15 13:55:50'),
(42, 'unit_sd_flow', 'Pembuatan Akun & Registrasi Awal di Portal SPMB\r\nPembayaran Biaya Awal Pendaftaran (Enrollment Fee)\r\nPengisian Formulir Lengkap & Unggah Dokumen Berkas\r\nVerifikasi & Validasi Berkas oleh Panitia SPMB\r\nAssessment Siswa & Sesi Ta\'aruf\r\nPengumuman Hasil Seleksi & Persetujuan Pernyataan\r\nDaftar Ulang & Penyelesaian Administrasi Akhir', '2026-09-04 01:24:33', '2026-09-12 02:01:38'),
(43, 'unit_smp_desc', 'Institusi pendidikan yang mencetak fitrah remaja yang mendorong kemandirian (independence) , resilience, dan rasa tanggungjawab, sehingga murid diproses menjadi calon pemimpin masa depan yang kuat, berkepribadian, visioner, inspiratif, dan humanis. \r\nPembentukan karakter murid didasarkan ekosistem ramah anak (childfriendly ecosystem approach) dengan fokus pada perbedaan individu murid (student individual differences).\r\nMencetak generasi yang berwawasan dan berkemampuan global, berdaya saing dan kolaboratif, serta berkarakter Islami (adab akhlaq al-karimah) berbasis Panca Karakter Anak Saleh.', '2026-09-04 01:24:33', '2026-09-12 01:07:05'),
(44, 'unit_smp_content', '- Special curriculum of Anak Saleh\r\n- International curriculum\r\n- National curriculum \r\n- Islamic curriculum', '2026-09-04 01:24:33', '2026-09-15 07:53:04'),
(45, 'unit_smp_features', '- Panca Karakter Anak Saleh\r\n- Hombebase System\r\n- Intra-School Organization\r\n- Digital School Ecosystem\r\n- IT and Coding Program\r\n- Project Based Learning\r\n- Cooperative Based Learning\r\n- Student Active Learning\r\n- STEAM Learning\r\n- Family Inn Learning\r\n- Multingual School (Indonesian, English, Arabic) \r\n- International Program (VISA : Visiting International School Abroad)', '2026-09-04 01:24:33', '2026-09-15 15:23:02'),
(46, 'unit_smp_requirements', '- Mengisi Formulir Pendaftaran, \r\n- Scan Akta Kelahiran\r\n- Scan Kartu Keluarga \r\n- Scan Surat Keterangan Murid Aktif Dari SD Asal\r\n- Passphoto formal \r\n- Scan NISN \r\n- Scan Surat Hasil Assessment Dari Psikolog (khusus MBK / Murid Berkebutuhan Khusus) \r\n- Surat Keterangan Peringkat Nilai Paralel (khusus top 10 peringkat nilai paralel SD Anak Saleh)', '2026-09-04 01:24:33', '2026-09-15 07:53:04'),
(47, 'unit_smp_flow', '- Pembuatan akun & registrasi awal di portal SPMB\r\n- Pembayaran biaya awal pendaftaran (enrollment fee) \r\n- Pengisian formulir lengkap dan unggah dokumen berkas\r\n- Verifikasi & validasi berkas oleh panitia SPMB\r\n- Assessment murid & sesi ta\'aruf\r\n- Pengumuman hasil seleksi & persetujuan pernyataan \r\n- Daftar ulang & penyelesaian administrasi akhir', '2026-09-04 01:24:33', '2026-09-16 08:08:35'),
