--
-- Table structure for table `spmb_agreement_templates`
--

CREATE TABLE `spmb_agreement_templates` (
  `id` bigint UNSIGNED NOT NULL,
  `spmb_unit_id` bigint UNSIGNED NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `rules_consent_label` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fees_consent_label` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `place` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Malang',
  `principal_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Dra. Hj. Mike Supraptiwi, S.Psi, M.Pd',
  `principal_title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Kepala Sekolah',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `spmb_agreement_templates`
--

INSERT INTO `spmb_agreement_templates` (`id`, `spmb_unit_id`, `title`, `content`, `rules_consent_label`, `fees_consent_label`, `place`, `principal_name`, `principal_title`, `created_at`, `updated_at`) VALUES
(1, 1, 'SURAT PERNYATAAN KESANGGUPAN MEMATUHI PERATURAN & BIAYA PENDIDIKAN YAYASAN PENDIDIKAN ANAK SALEH', '<p>Saya yang bertanda tangan di bawah ini selaku Orang Tua / Wali murid dari calon siswa:</p><p>Nama Calon Siswa : <strong>{{nama_calon_siswa}}</strong></p><p>Unit &amp; Program : <strong>{{nama_unit}} - {{nama_kelas}}</strong></p><p>Tahun Ajaran : <strong>{{tahun_ajaran}}</strong></p><p><br></p><p>Kami orangtua / wali dari murid di atas, baik sendiri maupun bersama pasangan kami beserta anak-anak yang kami percayakan pendidikannya di Sekolah Anak Saleh sebagai murid, dengan ini kami menyatakan bahwa kami <strong><em>memahami, sepakat, setuju, dan menerima</em> </strong>dengan sesungguhnya dan penuh kesadaran akan<em> </em>hal-hal sebagai berikut:</p><ol><li><strong>Kami bersedia dan menyetujui:</strong></li><li class=\"ql-indent-1\">Mematuhi semua peraturan, ketentuan, tata tertib, kebijakan, dan prosedur yang dibuat dan berlaku di Sekolah Anak Saleh, baik yang telah berlaku maupun yang akan diberlakukan di kemudian hari (selama tidak ada pihak yang dirugikan), baik tertulis maupun tidak tertulis, termasuk pada Peraturan Yayasan Pendidikan Anak Saleh, Tata Tertib, Kode Etik, dan lain- lain.</li><li class=\"ql-indent-1\">Menerima visi, misi, tujuan, metode, dan tata kelola Sekolah Anak Saleh dalam mendidik semua peserta didik di Sekolah Anak Saleh dan karenanya kami percaya bahwa segala peraturan dan arah kerja pendidikan yang dibuat oleh Sekolah Anak Saleh adalah untuk kebaikan peserta didik dan pihak sekolah.</li><li class=\"ql-indent-1\">Menerima implementasi, internalisasi, sosialisasi dan kulturisasi Panca Karakter Anak Saleh sebagai basis utama pembelajaran dan pendidikan karakter di lingkungan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Semua peserta didik wajib ikut serta dan / atau berpartisipasi dalam semua kegiatan Sekolah Anak Saleh. Kami menerima bahwa ketidakikutsertaan peserta didik dalam kegiatan tersebut dapat berakibat kepada penilaian hasil belajarnya di Sekolah Anak Saleh dan tidak menggugurkan kewajiban kami untuk membayar biaya pendidikan sesuai ketentuan yang berlaku sama bagi seluruh peserta didik yang mengikuti kegiatan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Aktif mengikuti, berpartisipasi, dan/ atau mendukung dalam kegiatan <em>parenting</em>, pengajian, bakti sosial / sosial keagamaan dan kegiatan <em>outdoor</em> serta <em>outing</em> yang diadakan Sekolah Anak Saleh dan / atau bekerjasama dengan forkel atau Komite Sekolah.</li><li class=\"ql-indent-1\">Menerima dan tidak mempertentangkan ajaran Islam <em>Ahli Sunnah wal Jama’ah yang Rahmatan Lil ‘Alamin </em>yang diajarkan di lingkungan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Menerima dan tidak menentang landasan yang digunakan di lingkungan Sekolah Anak Saleh yakni <em>Al-Qur’an, Al-Hadits, Ijma’, dan Qiyas </em>(termasuk di dalamnya hukum-hukum yang sah menurut Undang-Undang dan peraturan lain yang berlaku di Negara Kesatuan Republik Indonesia).</li><li class=\"ql-indent-1\">Tidak membawa kepentingan apapun ke dalam lingkungan Sekolah Anak Saleh baik kepada wali murid lain maupun kepada warga sekolah yang berkaitan dengan politik, ormas, dan kegiatan yang bersifat SARA atau yang dapat berpotensi memecah belah kerukunan.</li><li class=\"ql-indent-1\">Menerima dan mendukung segala bentuk program inklusi di lingkungan Sekolah Anak Saleh serta tidak mempermasalahkan keberadaan Peserta Didik Berkebutuhan Khusus (PDBK) di lingkungan Sekolah Anak Saleh sebagai komitmen bersama <em>education for all.</em></li><li class=\"ql-indent-1\">Apabila ananda masuk jalur reguler atau bukan jalur Peserta Didik Berkebutuhan Khusus (PDBK) maka akan bersedia menyediakan Guru Pembimbing Khusus (GPK) atau pendamping secara mandiri apabila dikemudian hari dalam perkembangannya ananda mengalami kendala yang masuk dalam kategori Peserta Didik Berkebutuhan Khusus (PDBK), serta tidak mempertentangkan atas keputusan pihak sekolah dalam memutuskan kebutuhan GPK terhadap ananda.</li><li class=\"ql-indent-1\">Memahami dan menyadari jika anak merupakan amanah Allah SWT yang harus dijaga dan dididik oleh orangtua / wali sebagai penerima utama amanah tersebut, sehingga akan berikhtiar dalam bekerjasama dengan Sekolah Anak Saleh untuk memperhatikan dan mengusahakan kesejahteraan fisik dan mental, tumbuh kembang dan pendidikannya dalam semangat cinta dan kasih.</li><li class=\"ql-indent-1\">Tidak melakukan ujaran maupun tindakan provokasi terhadap kebijakan sekolah serta menyampaikan kritik dan saran secara santun sesuai koridor kepada pimpinan sekolah, tidak dengan mengelaborasi masalah sehingga dapat menyebabkan kegaduhan atau polemik diantara sekolah maupun wali peserta didik lainnya. Jika menyampaikan kritik dan saran disampaikan secara santun sesuai koridor dan adab muslim serta adat masyarakat timur.</li><li class=\"ql-indent-1\">Memahami posisi dan kewenangan sebagai wali peserta didik dengan tidak mancampuri urusan yang menjadi ranah dan kewenangan Sekolah Anak Saleh antara lain: kurikulum dan pembelajaran (selama tidak keluar dari koridor nilai dan norma masyarakat maupun agama), administrasi dan manajemen sekolah, organisasi dan kelembagaan sekolah, ketenagaan, keuangan, sarana dan prasarana (selama tidak membahayakan warga sekolah), serta program kegiatan (selama tidak merugikan berbagai pihak).</li><li class=\"ql-indent-1\">Apabila dikemudian hari terdapat perselisihan dengan pihak sekolah maka bersedia untuk menyelesaikan dengan cara kekeluargaan serta tidak melibatkan pihak luar seperti Lembaga Swadaya Masyarakat (LSM) dan sejenisnya.</li><li class=\"ql-indent-1\">Bersedia mengganti rugi atas kelalaian yang disengaja maupun tidak atas kerusakan fasilitas sekolah yang disebabkan oleh anak kami.</li><li class=\"ql-indent-1\">Apabila terjadi hal-hal yang diluar kendali atau <em>force majeure </em>akan tetap berkomitmen untuk menyelesaikan segala bentuk kewajiban dengan tidak mempertentangkan kebijakan atau langkah strategis yang diambil oleh Yayasan Pendidikan Anak Saleh demi kebaikan bersama.</li><li class=\"ql-indent-1\">Mengikuti segala hal berdasarkan aturan dan penjelasan resmi dari pimpinan sekolah bukan atas kabar burung atau pernyataan sepihak yang tidak berdasar dari pihak manapun.</li><li><strong>Kami menyetujui pembiayaan di Sekolah Anak Saleh:</strong></li><li class=\"ql-indent-1\">Bahwa biaya pendidikan (<em>musa’adah, syahriyah</em>, dan pembiayaan lain yang ditentukan Yayasan Pendidikan Anak Saleh) yang harus dipenuhi selama peserta didik mengikuti pendidikan di Sekolah Anak Saleh dengan cara dan waktu pembayaran yang ditetapkan leh Yayasan menjadi tanggungjawab kami untuk membayarnya secara tepat waktu.</li><li class=\"ql-indent-1\">Bahwa kewajiban pembayaran biaya pendidikan yang terhitung (tunggakan) tidak dapat terhapus meski peserta didik sudah tidak mengikuti pendidikan di Sekolah Anak Saleh. Kami akan tetap menyelesaikan tunggakan sebagai hutang yang harus dibayarkan. Oleh karenanya kami akan menyelesaikan tunggakan tersebut sebelum anak kami tidak lagi mengikuti Pendidikan di Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Mengenai dana kegiatan, dana peralatan, dana makan, dan dana operasional sekolah, kami sepakat besaran dana tersebut adalah bagian tak terpisahkan dari biaya pendidikan yang wajib dibayar secara penuh dalam Dana Sekolah Tunggal (<em>Syahriyah</em>/ biaya bulanan), baik peserta didik yang bersangkutan ikut ataupun tidak, kegiatan atau program dimaksud karena alasan apapun.</li><li class=\"ql-indent-1\">Mengenai poin (2c) diatas kami memahami dan tidak mempertanyakan kembali apabila terdapat libur sekolah, puasa ramadhan, dan momen tertentu lainnya, karena perhitungan kegiatan, makan siang, dan lain-lain telah diperhitungkan oleh pihak Yayasan Pendidikan anak saleh dan dihitung rata setiap bulannya dalam bentuk Dana Sekolah Tunggal (<em>Syahriyah</em>/ biaya bulanan)</li><li class=\"ql-indent-1\">Mengenai poin (2c) diatas telah disebutkan terdapat Dana Sekolah Tunggal (syahriyah/ biaya bulanan) tersebut belum termasuk biaya kegiatan ke Luar negeri (akan terdapat hitungan kembali apabila kebijakan tersebut berjalan) serta belum termasuk perangkat pembelajaran yang wajib disediakan oleh orang tua berupa tablet siswa yang sesuai dengan spesifikasi yang diminta oleh pihak sekolah.</li><li class=\"ql-indent-1\">Sekolah Anak Saleh berwenang sepenuhnya untuk mengelola dan menggunakan dana <em>musa’adah</em>, <em>syahriyah</em>, kegiatan, peralatan, serta bantuan operasional oleh pemerintah untuk kegiatan bagi peserta didik atau keperluan lain yang dianggap perlu dan baik guna kemajuan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Disadari bahwa beban-beban penyelenggaraan pendidikan harus terus-menerus disesuaikan mengikuti inflasi, kenaikan biaya dan harga-harga, kenaikan berkala gaji pegawai (<em>bisyaroh</em>) dan sebagainya. Oleh karena itu kami orangtua dan / wali peserta didik bersedia menerima kenaikan <em>syahriyah </em>(biaya bulanan) sebesar 3% (tiga persen, dengan pembulatan nominal ke atas) dari nominal sebelumnya setiap tahunnya.</li><li class=\"ql-indent-1\">Bila kami belum bisa melunasi kewajiban biaya pendidikan yang harus dibayarkan, maka kami menyadari dan menerima bahwa setiap saat Sekolah Anak Saleh berwenang menunda pemberian hak akademik peserta didik yang bersangkutan, menahan raport, ijazah dan/atau dokumen lainnya sampai dengan kewajiban biaya pendidikan yang harus dibayarkan dapat dilunasi.</li><li class=\"ql-indent-1\">Kami akan menerima dan tidak mempertentangkan apabila ananda dikeluarkan oleh sekolah karena kelalaian maupun ketidakmampuan kami sebagai orang tua/ wali peserta didik dalam menyelesaikan tunggakan biaya sekolah sesuai aturan dan ketentuan yang belaku di lingkungan sekolah anak saleh.</li><li class=\"ql-indent-1\">Tidak akan memberikan hadiah / gratifikasi kepada asatidz dan karyawan maupun pimpinan Sekolah Anak Saleh secara perseorangan sehingga pemberian tersebut, disengaja untuk dapat mempengaruhi obyektivitas asatidz, dan karyawan maupun pimpinan Sekolah Anak Saleh terhadap peserta didik. Pemberian hadiah dapat dibenarkan apabila dilakukan tanpa permohonan tertentu dan diketahui oleh YPAS serta diatur oleh pimpinan sekolah yakni dengan tata cara yang dibenarkan menurut aturan yang berlaku di lingkungan sekolah (seperti hadiah ulang tahun, tasyakuran (kenaikan kelas/ kelulusan), selamatan, idul fitri, dan perpisahan)</li><li class=\"ql-indent-1\">Seluruh biaya pendaftaran dan pendidikan yang telah dibayarkan, tidak dapat diminta kembali dengan alasan apapun.</li><li><strong>Kami menyetujui bahwa Sekolah Anak Saleh berwenang untuk:</strong></li><li class=\"ql-indent-1\">Memberikan nilai dan keterangan terhadap peserta didik yang akan tertuang di dalam raport oleh asatidz sesuai dengan penilaian-penilaian yang telah dilakukan.</li><li class=\"ql-indent-1\">Menentukan penempatan kelas peserta didik atas pertimbangan oleh tim asatidz dengan persetujuan kepala sekolah.</li><li class=\"ql-indent-1\">Menentukan peserta didik yang dapat/tidak dapat naik kelas dan yang dapat/tidak dapat melanjutkan pendidikan di Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang perlu, termasuk memberhentikan peserta didik bila didapati di kemudian hari bahwa orangtua dan/wali peserta didik telah memberikan keterangan yang salah, palsu dan/atau menghilangkan sebagian atau seluruh keterangan tertentu mengenai data-data peserta didik serta dokumen-dokumen pendukungnya.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang perlu, termasuk memberhentikan peserta didik bila didapati di kemudian hari bahwa orangtua dan/wali peserta didik melakukan tindakan-tindakan merugikan warga sekolah maupun wali peserta didik lainnya seperti provokasi, menyebarkan berita bohong, dan tindakan merugikan lainnya yang dapat mengganggu ketenteraman dan kestabilan jalannya operasional Sekolah Anak Saleh serta tidak mempermasalahkan dikemudian hari dalam bentuk apapun.</li><li class=\"ql-indent-1\">Menindaklanjuti dengan menyesuaikan dengan program inklusi yang ada di Sekolah Anak Saleh ketika dalam proses perkembangannya peserta didik didiagnosa mengalami kebutuhan khusus dengan data-data dan hasil asesmen yang jelas/dari ahli yang disetujui pimpinan sekolah.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang dianggap perlu, termasuk memberi peringatan, melakukan <em>skorsing </em>hingga memberhentikan peserta didik apabila peserta didik kedapatan melakukan tindakan-tindakan berikut ini:</li><li class=\"ql-indent-2\">Melanggar peraturan sekolah dan tata tertib sekolah</li><li class=\"ql-indent-2\">Melakukan tindakan yang menyangkut <em>bullying</em> kepada warga sekolah lainnya</li><li class=\"ql-indent-2\">Tindakan perusakan fasilitas sekolah</li><li class=\"ql-indent-2\">Membawa, mengonsumsi dan/atau mengedarkan makanan dan/atau minuman yang mengandung alkohol, narkoba dan/atau obat-obatan terlarang lainnya.</li><li class=\"ql-indent-2\">Membawa, membaca, melihat, dan memperlihatkan dan/atau mengedarkan pornografi dalam berbagai bentuk dan/atau melakukan tindakan pornoaksi</li><li class=\"ql-indent-2\">Mencemarkan nama baik sekolah</li><li class=\"ql-indent-2\">Merusak kehormatan asatidz dan/atau merugikan peserta didik lainnya, serta</li><li class=\"ql-indent-2\">Tindakan-tindakan vandalisme lainnya yang tidak sejalan dengan visi dan misi sekolah secara langsung maupun tidak langsung.</li><li><strong>Kami bertanggung jawab atas urusan antar jemput:</strong></li><li class=\"ql-indent-1\">Bahwa antar jemput peserta didik ke / dari sekolah-rumah merupakan tanggungjawab kami sebagai keluarga.</li><li class=\"ql-indent-1\">Bahwa penggunaan mobil antar-jemput sekolah didasarkan pada unit yang ditunjuk dan direferensikan oleh sekolah. Kami tidak menyalahkan atau meminta tanggungjawab (menuntut) sekolah bilamana terjadi sesuatu hal karena penggunaan mobil antar jemput bukan yang ditunjuk / direferensi sekolah.</li><li class=\"ql-indent-1\">Bahwa pada waktu pulang sekolah, peserta didik wajib dijemput orangtua / wali atau yang mewakili dengan kesepakatan terlebih dahulu antara orangtua / wali dengan sekolah. Apabila ananda di jemput oleh siapapun dan ananda mengenal yang menjemput serta tidak menolak ketika di jemput, maka sekolah akan melepaskan ananda untuk di jemput orang tersebut. Dalam hal ini sekolah tidak dapat disalahkan jika terjadi hal-hal yang tidak diinginkan jika ananda yang bersangkutan di jemput, mengenali dan tidak menolak penjemputannya.</li></ol>', 'Saya menyetujui seluruh tata tertib dan peraturan akademik Sekolah Anak Saleh.', 'Saya menyanggupi pemenuhan seluruh rincian biaya pendidikan dan administrasi masuk yayasan.', 'Malang', '', '', '2026-09-04 01:23:32', '2026-09-16 12:22:18'),
(2, 2, 'SURAT PERNYATAAN KESANGGUPAN MEMATUHI PERATURAN & BIAYA PENDIDIKAN YAYASAN PENDIDIKAN ANAK SALEH', '<p>Saya yang bertanda tangan di bawah ini selaku Orang Tua / Wali murid dari calon siswa:</p><p>Nama Calon Siswa : <strong>{{nama_calon_siswa}}</strong></p><p>Unit &amp; Program : <strong>{{nama_unit}} - {{nama_kelas}}</strong></p><p>Tahun Ajaran : <strong>{{tahun_ajaran}}</strong></p><p><br></p><p>Kami orangtua / wali dari murid di atas, baik sendiri maupun bersama pasangan kami beserta anak-anak yang kami percayakan pendidikannya di Sekolah Anak Saleh sebagai murid, dengan ini kami menyatakan bahwa kami <strong><em>memahami, sepakat, setuju, dan menerima</em> </strong>dengan sesungguhnya dan penuh kesadaran akan<em> </em>hal-hal sebagai berikut:</p><ol><li><strong>Kami bersedia dan menyetujui:</strong></li><li class=\"ql-indent-1\">Mematuhi semua peraturan, ketentuan, tata tertib, kebijakan, dan prosedur yang dibuat dan berlaku di Sekolah Anak Saleh, baik yang telah berlaku maupun yang akan diberlakukan di kemudian hari (selama tidak ada pihak yang dirugikan), baik tertulis maupun tidak tertulis, termasuk pada Peraturan Yayasan Pendidikan Anak Saleh, Tata Tertib, Kode Etik, dan lain- lain.</li><li class=\"ql-indent-1\">Menerima visi, misi, tujuan, metode, dan tata kelola Sekolah Anak Saleh dalam mendidik semua peserta didik di Sekolah Anak Saleh dan karenanya kami percaya bahwa segala peraturan dan arah kerja pendidikan yang dibuat oleh Sekolah Anak Saleh adalah untuk kebaikan peserta didik dan pihak sekolah.</li><li class=\"ql-indent-1\">Menerima implementasi, internalisasi, sosialisasi dan kulturisasi Panca Karakter Anak Saleh sebagai basis utama pembelajaran dan pendidikan karakter di lingkungan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Semua peserta didik wajib ikut serta dan / atau berpartisipasi dalam semua kegiatan Sekolah Anak Saleh. Kami menerima bahwa ketidakikutsertaan peserta didik dalam kegiatan tersebut dapat berakibat kepada penilaian hasil belajarnya di Sekolah Anak Saleh dan tidak menggugurkan kewajiban kami untuk membayar biaya pendidikan sesuai ketentuan yang berlaku sama bagi seluruh peserta didik yang mengikuti kegiatan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Aktif mengikuti, berpartisipasi, dan/ atau mendukung dalam kegiatan <em>parenting</em>, pengajian, bakti sosial / sosial keagamaan dan kegiatan <em>outdoor</em> serta <em>outing</em> yang diadakan Sekolah Anak Saleh dan / atau bekerjasama dengan forkel atau Komite Sekolah.</li><li class=\"ql-indent-1\">Menerima dan tidak mempertentangkan ajaran Islam <em>Ahli Sunnah wal Jama’ah yang Rahmatan Lil ‘Alamin </em>yang diajarkan di lingkungan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Menerima dan tidak menentang landasan yang digunakan di lingkungan Sekolah Anak Saleh yakni <em>Al-Qur’an, Al-Hadits, Ijma’, dan Qiyas </em>(termasuk di dalamnya hukum-hukum yang sah menurut Undang-Undang dan peraturan lain yang berlaku di Negara Kesatuan Republik Indonesia).</li><li class=\"ql-indent-1\">Tidak membawa kepentingan apapun ke dalam lingkungan Sekolah Anak Saleh baik kepada wali murid lain maupun kepada warga sekolah yang berkaitan dengan politik, ormas, dan kegiatan yang bersifat SARA atau yang dapat berpotensi memecah belah kerukunan.</li><li class=\"ql-indent-1\">Menerima dan mendukung segala bentuk program inklusi di lingkungan Sekolah Anak Saleh serta tidak mempermasalahkan keberadaan Peserta Didik Berkebutuhan Khusus (PDBK) di lingkungan Sekolah Anak Saleh sebagai komitmen bersama <em>education for all.</em></li><li class=\"ql-indent-1\">Apabila ananda masuk jalur reguler atau bukan jalur Peserta Didik Berkebutuhan Khusus (PDBK) maka akan bersedia menyediakan Guru Pembimbing Khusus (GPK) atau pendamping secara mandiri apabila dikemudian hari dalam perkembangannya ananda mengalami kendala yang masuk dalam kategori Peserta Didik Berkebutuhan Khusus (PDBK), serta tidak mempertentangkan atas keputusan pihak sekolah dalam memutuskan kebutuhan GPK terhadap ananda.</li><li class=\"ql-indent-1\">Memahami dan menyadari jika anak merupakan amanah Allah SWT yang harus dijaga dan dididik oleh orangtua / wali sebagai penerima utama amanah tersebut, sehingga akan berikhtiar dalam bekerjasama dengan Sekolah Anak Saleh untuk memperhatikan dan mengusahakan kesejahteraan fisik dan mental, tumbuh kembang dan pendidikannya dalam semangat cinta dan kasih.</li><li class=\"ql-indent-1\">Tidak melakukan ujaran maupun tindakan provokasi terhadap kebijakan sekolah serta menyampaikan kritik dan saran secara santun sesuai koridor kepada pimpinan sekolah, tidak dengan mengelaborasi masalah sehingga dapat menyebabkan kegaduhan atau polemik diantara sekolah maupun wali peserta didik lainnya. Jika menyampaikan kritik dan saran disampaikan secara santun sesuai koridor dan adab muslim serta adat masyarakat timur.</li><li class=\"ql-indent-1\">Memahami posisi dan kewenangan sebagai wali peserta didik dengan tidak mancampuri urusan yang menjadi ranah dan kewenangan Sekolah Anak Saleh antara lain: kurikulum dan pembelajaran (selama tidak keluar dari koridor nilai dan norma masyarakat maupun agama), administrasi dan manajemen sekolah, organisasi dan kelembagaan sekolah, ketenagaan, keuangan, sarana dan prasarana (selama tidak membahayakan warga sekolah), serta program kegiatan (selama tidak merugikan berbagai pihak).</li><li class=\"ql-indent-1\">Apabila dikemudian hari terdapat perselisihan dengan pihak sekolah maka bersedia untuk menyelesaikan dengan cara kekeluargaan serta tidak melibatkan pihak luar seperti Lembaga Swadaya Masyarakat (LSM) dan sejenisnya.</li><li class=\"ql-indent-1\">Bersedia mengganti rugi atas kelalaian yang disengaja maupun tidak atas kerusakan fasilitas sekolah yang disebabkan oleh anak kami.</li><li class=\"ql-indent-1\">Apabila terjadi hal-hal yang diluar kendali atau <em>force majeure </em>akan tetap berkomitmen untuk menyelesaikan segala bentuk kewajiban dengan tidak mempertentangkan kebijakan atau langkah strategis yang diambil oleh Yayasan Pendidikan Anak Saleh demi kebaikan bersama.</li><li class=\"ql-indent-1\">Mengikuti segala hal berdasarkan aturan dan penjelasan resmi dari pimpinan sekolah bukan atas kabar burung atau pernyataan sepihak yang tidak berdasar dari pihak manapun.</li><li><strong>Kami menyetujui pembiayaan di Sekolah Anak Saleh:</strong></li><li class=\"ql-indent-1\">Bahwa biaya pendidikan (<em>musa’adah, syahriyah</em>, dan pembiayaan lain yang ditentukan Yayasan Pendidikan Anak Saleh) yang harus dipenuhi selama peserta didik mengikuti pendidikan di Sekolah Anak Saleh dengan cara dan waktu pembayaran yang ditetapkan leh Yayasan menjadi tanggungjawab kami untuk membayarnya secara tepat waktu.</li><li class=\"ql-indent-1\">Bahwa kewajiban pembayaran biaya pendidikan yang terhitung (tunggakan) tidak dapat terhapus meski peserta didik sudah tidak mengikuti pendidikan di Sekolah Anak Saleh. Kami akan tetap menyelesaikan tunggakan sebagai hutang yang harus dibayarkan. Oleh karenanya kami akan menyelesaikan tunggakan tersebut sebelum anak kami tidak lagi mengikuti Pendidikan di Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Mengenai dana kegiatan, dana peralatan, dana makan, dan dana operasional sekolah, kami sepakat besaran dana tersebut adalah bagian tak terpisahkan dari biaya pendidikan yang wajib dibayar secara penuh dalam Dana Sekolah Tunggal (<em>Syahriyah</em>/ biaya bulanan), baik peserta didik yang bersangkutan ikut ataupun tidak, kegiatan atau program dimaksud karena alasan apapun.</li><li class=\"ql-indent-1\">Mengenai poin (2c) diatas kami memahami dan tidak mempertanyakan kembali apabila terdapat libur sekolah, puasa ramadhan, dan momen tertentu lainnya, karena perhitungan kegiatan, makan siang, dan lain-lain telah diperhitungkan oleh pihak Yayasan Pendidikan anak saleh dan dihitung rata setiap bulannya dalam bentuk Dana Sekolah Tunggal (<em>Syahriyah</em>/ biaya bulanan)</li><li class=\"ql-indent-1\">Mengenai poin (2c) diatas telah disebutkan terdapat Dana Sekolah Tunggal (syahriyah/ biaya bulanan) tersebut belum termasuk biaya kegiatan ke Luar negeri (akan terdapat hitungan kembali apabila kebijakan tersebut berjalan) serta belum termasuk perangkat pembelajaran yang wajib disediakan oleh orang tua berupa tablet siswa yang sesuai dengan spesifikasi yang diminta oleh pihak sekolah.</li><li class=\"ql-indent-1\">Sekolah Anak Saleh berwenang sepenuhnya untuk mengelola dan menggunakan dana <em>musa’adah</em>, <em>syahriyah</em>, kegiatan, peralatan, serta bantuan operasional oleh pemerintah untuk kegiatan bagi peserta didik atau keperluan lain yang dianggap perlu dan baik guna kemajuan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Disadari bahwa beban-beban penyelenggaraan pendidikan harus terus-menerus disesuaikan mengikuti inflasi, kenaikan biaya dan harga-harga, kenaikan berkala gaji pegawai (<em>bisyaroh</em>) dan sebagainya. Oleh karena itu kami orangtua dan / wali peserta didik bersedia menerima kenaikan <em>syahriyah </em>(biaya bulanan) sebesar 3% (tiga persen, dengan pembulatan nominal ke atas) dari nominal sebelumnya setiap tahunnya.</li><li class=\"ql-indent-1\">Bila kami belum bisa melunasi kewajiban biaya pendidikan yang harus dibayarkan, maka kami menyadari dan menerima bahwa setiap saat Sekolah Anak Saleh berwenang menunda pemberian hak akademik peserta didik yang bersangkutan, menahan raport, ijazah dan/atau dokumen lainnya sampai dengan kewajiban biaya pendidikan yang harus dibayarkan dapat dilunasi.</li><li class=\"ql-indent-1\">Kami akan menerima dan tidak mempertentangkan apabila ananda dikeluarkan oleh sekolah karena kelalaian maupun ketidakmampuan kami sebagai orang tua/ wali peserta didik dalam menyelesaikan tunggakan biaya sekolah sesuai aturan dan ketentuan yang belaku di lingkungan sekolah anak saleh.</li><li class=\"ql-indent-1\">Tidak akan memberikan hadiah / gratifikasi kepada asatidz dan karyawan maupun pimpinan Sekolah Anak Saleh secara perseorangan sehingga pemberian tersebut, disengaja untuk dapat mempengaruhi obyektivitas asatidz, dan karyawan maupun pimpinan Sekolah Anak Saleh terhadap peserta didik. Pemberian hadiah dapat dibenarkan apabila dilakukan tanpa permohonan tertentu dan diketahui oleh YPAS serta diatur oleh pimpinan sekolah yakni dengan tata cara yang dibenarkan menurut aturan yang berlaku di lingkungan sekolah (seperti hadiah ulang tahun, tasyakuran (kenaikan kelas/ kelulusan), selamatan, idul fitri, dan perpisahan)</li><li class=\"ql-indent-1\">Seluruh biaya pendaftaran dan pendidikan yang telah dibayarkan, tidak dapat diminta kembali dengan alasan apapun.</li><li><strong>Kami menyetujui bahwa Sekolah Anak Saleh berwenang untuk:</strong></li><li class=\"ql-indent-1\">Memberikan nilai dan keterangan terhadap peserta didik yang akan tertuang di dalam raport oleh asatidz sesuai dengan penilaian-penilaian yang telah dilakukan.</li><li class=\"ql-indent-1\">Menentukan penempatan kelas peserta didik atas pertimbangan oleh tim asatidz dengan persetujuan kepala sekolah.</li><li class=\"ql-indent-1\">Menentukan peserta didik yang dapat/tidak dapat naik kelas dan yang dapat/tidak dapat melanjutkan pendidikan di Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang perlu, termasuk memberhentikan peserta didik bila didapati di kemudian hari bahwa orangtua dan/wali peserta didik telah memberikan keterangan yang salah, palsu dan/atau menghilangkan sebagian atau seluruh keterangan tertentu mengenai data-data peserta didik serta dokumen-dokumen pendukungnya.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang perlu, termasuk memberhentikan peserta didik bila didapati di kemudian hari bahwa orangtua dan/wali peserta didik melakukan tindakan-tindakan merugikan warga sekolah maupun wali peserta didik lainnya seperti provokasi, menyebarkan berita bohong, dan tindakan merugikan lainnya yang dapat mengganggu ketenteraman dan kestabilan jalannya operasional Sekolah Anak Saleh serta tidak mempermasalahkan dikemudian hari dalam bentuk apapun.</li><li class=\"ql-indent-1\">Menindaklanjuti dengan menyesuaikan dengan program inklusi yang ada di Sekolah Anak Saleh ketika dalam proses perkembangannya peserta didik didiagnosa mengalami kebutuhan khusus dengan data-data dan hasil asesmen yang jelas/dari ahli yang disetujui pimpinan sekolah.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang dianggap perlu, termasuk memberi peringatan, melakukan <em>skorsing </em>hingga memberhentikan peserta didik apabila peserta didik kedapatan melakukan tindakan-tindakan berikut ini:</li><li class=\"ql-indent-2\">Melanggar peraturan sekolah dan tata tertib sekolah</li><li class=\"ql-indent-2\">Melakukan tindakan yang menyangkut <em>bullying</em> kepada warga sekolah lainnya</li><li class=\"ql-indent-2\">Tindakan perusakan fasilitas sekolah</li><li class=\"ql-indent-2\">Membawa, mengonsumsi dan/atau mengedarkan makanan dan/atau minuman yang mengandung alkohol, narkoba dan/atau obat-obatan terlarang lainnya.</li><li class=\"ql-indent-2\">Membawa, membaca, melihat, dan memperlihatkan dan/atau mengedarkan pornografi dalam berbagai bentuk dan/atau melakukan tindakan pornoaksi</li><li class=\"ql-indent-2\">Mencemarkan nama baik sekolah</li><li class=\"ql-indent-2\">Merusak kehormatan asatidz dan/atau merugikan peserta didik lainnya, serta</li><li class=\"ql-indent-2\">Tindakan-tindakan vandalisme lainnya yang tidak sejalan dengan visi dan misi sekolah secara langsung maupun tidak langsung.</li><li><strong>Kami bertanggung jawab atas urusan antar jemput:</strong></li><li class=\"ql-indent-1\">Bahwa antar jemput peserta didik ke / dari sekolah-rumah merupakan tanggungjawab kami sebagai keluarga.</li><li class=\"ql-indent-1\">Bahwa penggunaan mobil antar-jemput sekolah didasarkan pada unit yang ditunjuk dan direferensikan oleh sekolah. Kami tidak menyalahkan atau meminta tanggungjawab (menuntut) sekolah bilamana terjadi sesuatu hal karena penggunaan mobil antar jemput bukan yang ditunjuk / direferensi sekolah.</li><li class=\"ql-indent-1\">Bahwa pada waktu pulang sekolah, peserta didik wajib dijemput orangtua / wali atau yang mewakili dengan kesepakatan terlebih dahulu antara orangtua / wali dengan sekolah. Apabila ananda di jemput oleh siapapun dan ananda mengenal yang menjemput serta tidak menolak ketika di jemput, maka sekolah akan melepaskan ananda untuk di jemput orang tersebut. Dalam hal ini sekolah tidak dapat disalahkan jika terjadi hal-hal yang tidak diinginkan jika ananda yang bersangkutan di jemput, mengenali dan tidak menolak penjemputannya.</li></ol>', 'Saya menyetujui seluruh tata tertib dan peraturan akademik Sekolah Anak Saleh.', 'Saya menyanggupi pemenuhan seluruh rincian biaya pendidikan dan administrasi masuk yayasan.', 'Malang', '', '', '2026-09-04 01:23:32', '2026-09-16 12:21:50'),
(3, 3, 'SURAT PERNYATAAN \r\nKOMITMEN ORANGTUA / WALI MURID\r\nSEKOLAH ANAK SALEH KOTA MALANG\r\n TAHUN AJARAN 2027/2028', '<p>Saya yang bertanda tangan di bawah ini selaku Orang Tua / Wali murid dari calon siswa:</p><p>Nama Calon Siswa : <strong>{{nama_calon_siswa}}</strong></p><p>Unit &amp; Program : <strong>{{nama_unit}} - {{nama_kelas}}</strong></p><p>Tahun Ajaran : <strong>{{tahun_ajaran}}</strong></p><p><br></p><p>Kami orangtua / wali dari murid di atas, baik sendiri maupun bersama pasangan kami beserta anak-anak yang kami percayakan pendidikannya di Sekolah Anak Saleh sebagai murid, dengan ini kami menyatakan bahwa kami <strong><em>memahami, sepakat, setuju, dan menerima</em> </strong>dengan sesungguhnya dan penuh kesadaran akan<em> </em>hal-hal sebagai berikut:</p><ol><li><strong>Kami bersedia dan menyetujui:</strong></li><li class=\"ql-indent-1\">Mematuhi semua peraturan, ketentuan, tata tertib, kebijakan, dan prosedur yang dibuat dan berlaku di Sekolah Anak Saleh, baik yang telah berlaku maupun yang akan diberlakukan di kemudian hari (selama tidak ada pihak yang dirugikan), baik tertulis maupun tidak tertulis, termasuk pada Peraturan Yayasan Pendidikan Anak Saleh, Tata Tertib, Kode Etik, dan lain- lain.</li><li class=\"ql-indent-1\">Menerima visi, misi, tujuan, metode, dan tata kelola Sekolah Anak Saleh dalam mendidik semua peserta didik di Sekolah Anak Saleh dan karenanya kami percaya bahwa segala peraturan dan arah kerja pendidikan yang dibuat oleh Sekolah Anak Saleh adalah untuk kebaikan peserta didik dan pihak sekolah.</li><li class=\"ql-indent-1\">Menerima implementasi, internalisasi, sosialisasi dan kulturisasi Panca Karakter Anak Saleh sebagai basis utama pembelajaran dan pendidikan karakter di lingkungan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Semua peserta didik wajib ikut serta dan / atau berpartisipasi dalam semua kegiatan Sekolah Anak Saleh. Kami menerima bahwa ketidakikutsertaan peserta didik dalam kegiatan tersebut dapat berakibat kepada penilaian hasil belajarnya di Sekolah Anak Saleh dan tidak menggugurkan kewajiban kami untuk membayar biaya pendidikan sesuai ketentuan yang berlaku sama bagi seluruh peserta didik yang mengikuti kegiatan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Aktif mengikuti, berpartisipasi, dan/ atau mendukung dalam kegiatan <em>parenting</em>, pengajian, bakti sosial / sosial keagamaan dan kegiatan <em>outdoor</em> serta <em>outing</em> yang diadakan Sekolah Anak Saleh dan / atau bekerjasama dengan forkel atau Komite Sekolah.</li><li class=\"ql-indent-1\">Menerima dan tidak mempertentangkan ajaran Islam <em>Ahli Sunnah wal Jama’ah yang Rahmatan Lil ‘Alamin </em>yang diajarkan di lingkungan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Menerima dan tidak menentang landasan yang digunakan di lingkungan Sekolah Anak Saleh yakni <em>Al-Qur’an, Al-Hadits, Ijma’, dan Qiyas </em>(termasuk di dalamnya hukum-hukum yang sah menurut Undang-Undang dan peraturan lain yang berlaku di Negara Kesatuan Republik Indonesia).</li><li class=\"ql-indent-1\">Tidak membawa kepentingan apapun ke dalam lingkungan Sekolah Anak Saleh baik kepada wali murid lain maupun kepada warga sekolah yang berkaitan dengan politik, ormas, dan kegiatan yang bersifat SARA atau yang dapat berpotensi memecah belah kerukunan.</li><li class=\"ql-indent-1\">Menerima dan mendukung segala bentuk program inklusi di lingkungan Sekolah Anak Saleh serta tidak mempermasalahkan keberadaan Peserta Didik Berkebutuhan Khusus (PDBK) di lingkungan Sekolah Anak Saleh sebagai komitmen bersama <em>education for all.</em></li><li class=\"ql-indent-1\">Apabila ananda masuk jalur reguler atau bukan jalur Peserta Didik Berkebutuhan Khusus (PDBK) maka akan bersedia menyediakan Guru Pembimbing Khusus (GPK) atau pendamping secara mandiri apabila dikemudian hari dalam perkembangannya ananda mengalami kendala yang masuk dalam kategori Peserta Didik Berkebutuhan Khusus (PDBK), serta tidak mempertentangkan atas keputusan pihak sekolah dalam memutuskan kebutuhan GPK terhadap ananda.</li><li class=\"ql-indent-1\">Memahami dan menyadari jika anak merupakan amanah Allah SWT yang harus dijaga dan dididik oleh orangtua / wali sebagai penerima utama amanah tersebut, sehingga akan berikhtiar dalam bekerjasama dengan Sekolah Anak Saleh untuk memperhatikan dan mengusahakan kesejahteraan fisik dan mental, tumbuh kembang dan pendidikannya dalam semangat cinta dan kasih.</li><li class=\"ql-indent-1\">Tidak melakukan ujaran maupun tindakan provokasi terhadap kebijakan sekolah serta menyampaikan kritik dan saran secara santun sesuai koridor kepada pimpinan sekolah, tidak dengan mengelaborasi masalah sehingga dapat menyebabkan kegaduhan atau polemik diantara sekolah maupun wali peserta didik lainnya. Jika menyampaikan kritik dan saran disampaikan secara santun sesuai koridor dan adab muslim serta adat masyarakat timur.</li><li class=\"ql-indent-1\">Memahami posisi dan kewenangan sebagai wali peserta didik dengan tidak mancampuri urusan yang menjadi ranah dan kewenangan Sekolah Anak Saleh antara lain: kurikulum dan pembelajaran (selama tidak keluar dari koridor nilai dan norma masyarakat maupun agama), administrasi dan manajemen sekolah, organisasi dan kelembagaan sekolah, ketenagaan, keuangan, sarana dan prasarana (selama tidak membahayakan warga sekolah), serta program kegiatan (selama tidak merugikan berbagai pihak).</li><li class=\"ql-indent-1\">Apabila dikemudian hari terdapat perselisihan dengan pihak sekolah maka bersedia untuk menyelesaikan dengan cara kekeluargaan serta tidak melibatkan pihak luar seperti Lembaga Swadaya Masyarakat (LSM) dan sejenisnya.</li><li class=\"ql-indent-1\">Bersedia mengganti rugi atas kelalaian yang disengaja maupun tidak atas kerusakan fasilitas sekolah yang disebabkan oleh anak kami.</li><li class=\"ql-indent-1\">Apabila terjadi hal-hal yang diluar kendali atau <em>force majeure </em>akan tetap berkomitmen untuk menyelesaikan segala bentuk kewajiban dengan tidak mempertentangkan kebijakan atau langkah strategis yang diambil oleh Yayasan Pendidikan Anak Saleh demi kebaikan bersama.</li><li class=\"ql-indent-1\">Mengikuti segala hal berdasarkan aturan dan penjelasan resmi dari pimpinan sekolah bukan atas kabar burung atau pernyataan sepihak yang tidak berdasar dari pihak manapun.</li><li><strong>Kami menyetujui pembiayaan di Sekolah Anak Saleh:</strong></li><li class=\"ql-indent-1\">Bahwa biaya pendidikan (<em>musa’adah, syahriyah</em>, dan pembiayaan lain yang ditentukan Yayasan Pendidikan Anak Saleh) yang harus dipenuhi selama peserta didik mengikuti pendidikan di Sekolah Anak Saleh dengan cara dan waktu pembayaran yang ditetapkan leh Yayasan menjadi tanggungjawab kami untuk membayarnya secara tepat waktu.</li><li class=\"ql-indent-1\">Bahwa kewajiban pembayaran biaya pendidikan yang terhitung (tunggakan) tidak dapat terhapus meski peserta didik sudah tidak mengikuti pendidikan di Sekolah Anak Saleh. Kami akan tetap menyelesaikan tunggakan sebagai hutang yang harus dibayarkan. Oleh karenanya kami akan menyelesaikan tunggakan tersebut sebelum anak kami tidak lagi mengikuti Pendidikan di Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Mengenai dana kegiatan, dana peralatan, dana makan, dan dana operasional sekolah, kami sepakat besaran dana tersebut adalah bagian tak terpisahkan dari biaya pendidikan yang wajib dibayar secara penuh dalam Dana Sekolah Tunggal (<em>Syahriyah</em>/ biaya bulanan), baik peserta didik yang bersangkutan ikut ataupun tidak, kegiatan atau program dimaksud karena alasan apapun.</li><li class=\"ql-indent-1\">Mengenai poin (2c) diatas kami memahami dan tidak mempertanyakan kembali apabila terdapat libur sekolah, puasa ramadhan, dan momen tertentu lainnya, karena perhitungan kegiatan, makan siang, dan lain-lain telah diperhitungkan oleh pihak Yayasan Pendidikan anak saleh dan dihitung rata setiap bulannya dalam bentuk Dana Sekolah Tunggal (<em>Syahriyah</em>/ biaya bulanan)</li><li class=\"ql-indent-1\">Mengenai poin (2c) diatas telah disebutkan terdapat Dana Sekolah Tunggal (syahriyah/ biaya bulanan) tersebut belum termasuk biaya kegiatan ke Luar negeri (akan terdapat hitungan kembali apabila kebijakan tersebut berjalan) serta belum termasuk perangkat pembelajaran yang wajib disediakan oleh orang tua berupa tablet siswa yang sesuai dengan spesifikasi yang diminta oleh pihak sekolah.</li><li class=\"ql-indent-1\">Sekolah Anak Saleh berwenang sepenuhnya untuk mengelola dan menggunakan dana <em>musa’adah</em>, <em>syahriyah</em>, kegiatan, peralatan, serta bantuan operasional oleh pemerintah untuk kegiatan bagi peserta didik atau keperluan lain yang dianggap perlu dan baik guna kemajuan Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Disadari bahwa beban-beban penyelenggaraan pendidikan harus terus-menerus disesuaikan mengikuti inflasi, kenaikan biaya dan harga-harga, kenaikan berkala gaji pegawai (<em>bisyaroh</em>) dan sebagainya. Oleh karena itu kami orangtua dan / wali peserta didik bersedia menerima kenaikan <em>syahriyah </em>(biaya bulanan) sebesar 3% (tiga persen, dengan pembulatan nominal ke atas) dari nominal sebelumnya setiap tahunnya.</li><li class=\"ql-indent-1\">Bila kami belum bisa melunasi kewajiban biaya pendidikan yang harus dibayarkan, maka kami menyadari dan menerima bahwa setiap saat Sekolah Anak Saleh berwenang menunda pemberian hak akademik peserta didik yang bersangkutan, menahan raport, ijazah dan/atau dokumen lainnya sampai dengan kewajiban biaya pendidikan yang harus dibayarkan dapat dilunasi.</li><li class=\"ql-indent-1\">Kami akan menerima dan tidak mempertentangkan apabila ananda dikeluarkan oleh sekolah karena kelalaian maupun ketidakmampuan kami sebagai orang tua/ wali peserta didik dalam menyelesaikan tunggakan biaya sekolah sesuai aturan dan ketentuan yang belaku di lingkungan sekolah anak saleh.</li><li class=\"ql-indent-1\">Tidak akan memberikan hadiah / gratifikasi kepada asatidz dan karyawan maupun pimpinan Sekolah Anak Saleh secara perseorangan sehingga pemberian tersebut, disengaja untuk dapat mempengaruhi obyektivitas asatidz, dan karyawan maupun pimpinan Sekolah Anak Saleh terhadap peserta didik. Pemberian hadiah dapat dibenarkan apabila dilakukan tanpa permohonan tertentu dan diketahui oleh YPAS serta diatur oleh pimpinan sekolah yakni dengan tata cara yang dibenarkan menurut aturan yang berlaku di lingkungan sekolah (seperti hadiah ulang tahun, tasyakuran (kenaikan kelas/ kelulusan), selamatan, idul fitri, dan perpisahan)</li><li class=\"ql-indent-1\">Seluruh biaya pendaftaran dan pendidikan yang telah dibayarkan, tidak dapat diminta kembali dengan alasan apapun.</li><li><strong>Kami menyetujui bahwa Sekolah Anak Saleh berwenang untuk:</strong></li><li class=\"ql-indent-1\">Memberikan nilai dan keterangan terhadap peserta didik yang akan tertuang di dalam raport oleh asatidz sesuai dengan penilaian-penilaian yang telah dilakukan.</li><li class=\"ql-indent-1\">Menentukan penempatan kelas peserta didik atas pertimbangan oleh tim asatidz dengan persetujuan kepala sekolah.</li><li class=\"ql-indent-1\">Menentukan peserta didik yang dapat/tidak dapat naik kelas dan yang dapat/tidak dapat melanjutkan pendidikan di Sekolah Anak Saleh.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang perlu, termasuk memberhentikan peserta didik bila didapati di kemudian hari bahwa orangtua dan/wali peserta didik telah memberikan keterangan yang salah, palsu dan/atau menghilangkan sebagian atau seluruh keterangan tertentu mengenai data-data peserta didik serta dokumen-dokumen pendukungnya.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang perlu, termasuk memberhentikan peserta didik bila didapati di kemudian hari bahwa orangtua dan/wali peserta didik melakukan tindakan-tindakan merugikan warga sekolah maupun wali peserta didik lainnya seperti provokasi, menyebarkan berita bohong, dan tindakan merugikan lainnya yang dapat mengganggu ketenteraman dan kestabilan jalannya operasional Sekolah Anak Saleh serta tidak mempermasalahkan dikemudian hari dalam bentuk apapun.</li><li class=\"ql-indent-1\">Menindaklanjuti dengan menyesuaikan dengan program inklusi yang ada di Sekolah Anak Saleh ketika dalam proses perkembangannya peserta didik didiagnosa mengalami kebutuhan khusus dengan data-data dan hasil asesmen yang jelas/dari ahli yang disetujui pimpinan sekolah.</li><li class=\"ql-indent-1\">Mengambil segala tindakan yang dianggap perlu, termasuk memberi peringatan, melakukan <em>skorsing </em>hingga memberhentikan peserta didik apabila peserta didik kedapatan melakukan tindakan-tindakan berikut ini:</li><li class=\"ql-indent-2\">Melanggar peraturan sekolah dan tata tertib sekolah</li><li class=\"ql-indent-2\">Melakukan tindakan yang menyangkut <em>bullying</em> kepada warga sekolah lainnya</li><li class=\"ql-indent-2\">Tindakan perusakan fasilitas sekolah</li><li class=\"ql-indent-2\">Membawa, mengonsumsi dan/atau mengedarkan makanan dan/atau minuman yang mengandung alkohol, narkoba dan/atau obat-obatan terlarang lainnya.</li><li class=\"ql-indent-2\">Membawa, membaca, melihat, dan memperlihatkan dan/atau mengedarkan pornografi dalam berbagai bentuk dan/atau melakukan tindakan pornoaksi</li><li class=\"ql-indent-2\">Mencemarkan nama baik sekolah</li><li class=\"ql-indent-2\">Merusak kehormatan asatidz dan/atau merugikan peserta didik lainnya, serta</li><li class=\"ql-indent-2\">Tindakan-tindakan vandalisme lainnya yang tidak sejalan dengan visi dan misi sekolah secara langsung maupun tidak langsung.</li><li><strong>Kami bertanggung jawab atas urusan antar jemput:</strong></li><li class=\"ql-indent-1\">Bahwa antar jemput peserta didik ke / dari sekolah-rumah merupakan tanggungjawab kami sebagai keluarga.</li><li class=\"ql-indent-1\">Bahwa penggunaan mobil antar-jemput sekolah didasarkan pada unit yang ditunjuk dan direferensikan oleh sekolah. Kami tidak menyalahkan atau meminta tanggungjawab (menuntut) sekolah bilamana terjadi sesuatu hal karena penggunaan mobil antar jemput bukan yang ditunjuk / direferensi sekolah.</li><li class=\"ql-indent-1\">Bahwa pada waktu pulang sekolah, peserta didik wajib dijemput orangtua / wali atau yang mewakili dengan kesepakatan terlebih dahulu antara orangtua / wali dengan sekolah. Apabila ananda di jemput oleh siapapun dan ananda mengenal yang menjemput serta tidak menolak ketika di jemput, maka sekolah akan melepaskan ananda untuk di jemput orang tersebut. Dalam hal ini sekolah tidak dapat disalahkan jika terjadi hal-hal yang tidak diinginkan jika ananda yang bersangkutan di jemput, mengenali dan tidak menolak penjemputannya.</li></ol>', 'Saya menyetujui seluruh tata tertib dan peraturan akademik Sekolah Anak Saleh.', 'Saya menyanggupi pemenuhan seluruh rincian biaya pendidikan dan administrasi masuk yayasan.', 'Malang', '', '', '2026-09-04 01:23:32', '2026-09-16 12:21:21');

